-- MIGRATION 1: base
CREATE TABLE roles (id BIGINT PRIMARY KEY, name VARCHAR(80) NOT NULL UNIQUE);
CREATE TABLE users (id BIGINT PRIMARY KEY, role_id BIGINT NOT NULL REFERENCES roles(id) ON DELETE RESTRICT, email VARCHAR(255) NOT NULL UNIQUE);
CREATE TABLE orders (id BIGINT PRIMARY KEY, user_id BIGINT NOT NULL, total NUMERIC(12,2) NOT NULL DEFAULT 0, CONSTRAINT fk_orders_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE INDEX idx_users_role ON users(role_id);
CREATE VIEW active_users AS SELECT id,email FROM users;
CREATE FUNCTION touch_user() RETURNS trigger AS $$ BEGIN RETURN NEW; END; $$ LANGUAGE plpgsql;
CREATE TRIGGER trg_users_touch BEFORE UPDATE ON users FOR EACH ROW EXECUTE FUNCTION touch_user();
